TArray<T> GetClosestSnapElementsFromPoint(const FVector& referencePoint, TArrayView<const T> elements, ESNDistancePlane distancePlane, int numClosestElements = 1) {
    TArray<T> closestElements;
    closestElements.Reserve(numClosestElements);

